"""Meta-tests for scripts/check_generated.py (INV-19): a hand-edited or stale generated file is flagged."""

from __future__ import annotations

import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

import check_generated as cg  # noqa: E402

GOOD = "<!-- GENERATED by x. Do not edit. -->\nbody\n"


class GeneratedCheck(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)
        self.patches = [
            mock.patch.object(cg, "ROOT", self.root),
            mock.patch.object(cg, "GENERATORS", {"out.md": (["gen"], ["src.toml"])}),
            mock.patch.object(cg, "expected", lambda path: GOOD),
        ]
        for p in self.patches:
            p.start()

    def tearDown(self) -> None:
        for p in self.patches:
            p.stop()
        self.tmp.cleanup()

    def test_fresh_output_passes(self) -> None:
        (self.root / "out.md").write_text(GOOD)
        self.assertEqual(cg.check_one("out.md", staged=False), [])

    def test_hand_edit_is_flagged(self) -> None:
        (self.root / "out.md").write_text(GOOD + "edited by hand\n")
        self.assertTrue(cg.check_one("out.md", staged=False))

    def test_missing_header_is_flagged(self) -> None:
        (self.root / "out.md").write_text("body\n")
        self.assertTrue(any("header" in p for p in cg.check_one("out.md", staged=False)))

    def test_missing_file_is_flagged(self) -> None:
        self.assertTrue(cg.check_one("out.md", staged=False))

    def test_empty_file_is_flagged_not_crashing(self) -> None:
        (self.root / "out.md").write_text("")
        self.assertTrue(cg.check_one("out.md", staged=False))

    def test_unregistered_file_under_design_generated(self) -> None:
        (self.root / "design/generated").mkdir(parents=True)
        (self.root / "design/generated/stray.md").write_text("x")
        (self.root / "out.md").write_text(GOOD)
        self.assertEqual(cg.main(["--only", "out.md"]), 1)


GOOD_JSON = '{\n  "$comment": "GENERATED by x. Do not edit.",\n  "a": 1\n}\n'


class JsonArtifacts(unittest.TestCase):
    """A JSON file cannot carry a comment line: its header is the top-level `$comment` key, first in the object
    (S0035; the engine protocol schema is the first generated JSON file)."""

    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)
        self.have = GOOD_JSON
        self.patches = [
            mock.patch.object(cg, "ROOT", self.root),
            mock.patch.object(cg, "GENERATORS", {"out.json": (["gen"], ["src.py"])}),
        ]
        for p in self.patches:
            p.start()

    def tearDown(self) -> None:
        for p in self.patches:
            p.stop()
        self.tmp.cleanup()

    def check(self, text: str) -> list[str]:
        (self.root / "out.json").write_text(text)
        with mock.patch.object(cg, "expected", lambda path: text):  # fresh output equal: only the header counts
            return cg.check_one("out.json", staged=False)

    def test_a_json_header_passes(self) -> None:
        self.assertEqual(self.check(GOOD_JSON), [])

    def test_json_without_the_header_is_flagged(self) -> None:
        self.assertTrue(any("header" in p for p in self.check('{\n  "a": 1\n}\n')))

    def test_a_header_that_is_not_the_first_key_is_flagged(self) -> None:
        self.assertTrue(any("header" in p for p in self.check('{"a": 1, "$comment": "GENERATED by x"}\n')))

    def test_a_comment_without_the_mark_is_flagged(self) -> None:
        self.assertTrue(any("header" in p for p in self.check('{"$comment": "hand-written", "a": 1}\n')))

    def test_the_mark_in_a_nested_comment_is_not_a_header(self) -> None:
        self.assertTrue(any("header" in p for p in self.check('{"a": {"$comment": "GENERATED"}}\n')))

    def test_invalid_json_is_flagged(self) -> None:
        self.assertTrue(any("header" in p for p in self.check('{"$comment": "GENERATED by x",\n')))

    def test_a_hand_edit_is_flagged(self) -> None:
        (self.root / "out.json").write_text(GOOD_JSON.replace('"a": 1', '"a": 2'))
        with mock.patch.object(cg, "expected", lambda path: GOOD_JSON):
            self.assertTrue(cg.check_one("out.json", staged=False))


class EngineSchema(unittest.TestCase):
    """The engine protocol schema is registered, generated in the engine's environment (ADR-0054 decision 2)."""

    PATH = "contracts/engine-protocol.schema.json"

    def test_registered_with_the_engine_models_as_sources(self) -> None:
        cmd, sources = cg.GENERATORS[self.PATH]
        self.assertIn("engine/src/ledger_engine/protocol/messages.py", sources)
        self.assertIn("engine/src/ledger_engine/protocol/schema.py", sources)
        self.assertIn("engine/uv.lock", sources)  # a pydantic upgrade can change the output
        self.assertIn("ledger_engine.protocol.schema", cmd)

    def test_a_generator_that_cannot_run_is_a_problem_not_a_crash(self) -> None:
        with tempfile.TemporaryDirectory() as tmp, \
                mock.patch.object(cg, "ROOT", Path(tmp)), \
                mock.patch.object(cg, "GENERATORS", {"out.json": ([str(Path(tmp) / "no-such-python"), "-c", ""], [])}):
            (Path(tmp) / "out.json").write_text(GOOD_JSON)
            problems = cg.check_one("out.json", staged=False)
        self.assertTrue(any("could not run" in p for p in problems), problems)


if __name__ == "__main__":
    unittest.main()
